import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;
    static int[] parent;
    static int nc;

    static int find(int x) {
        if (parent[x] == x) return x;
        parent[x] = find(parent[x]);
        return parent[x];
    }

    static void merge(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        nc--;
        parent[b] = a;
    }

    static long fmp(long x, int e) {
        if (e == 0) return 1;
        long w = fmp(x, e / 2);
        w = (w * w) % MOD;
        if ((e & 1) == 1) w = (w * x) % MOD;
        return w;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(fmp(p, (int) p - 1));
            return;
        }

        parent = new int[(int) p];
        nc = (int) p - (k > 1 ? 1 : 0);

        for (int i = 1; i < p; i++) {
            parent[i] = i;
        }

        for (int i = 1; i < p; i++) {
            merge(i, (int) ((i * k) % p));
        }

        System.out.println(fmp(p, nc));
    }
}
